replacement.after:
if (part.status === 'failed') {
  // tool.failed 的结构化消息优先；业务失败的 tool.completed(isError) 由 resultText 保留原因。
  // 仅展示 SDK 的非空文本字段，不序列化原始 result/error 对象；el 恒通过 textContent 落 DOM。
  const message = [part.errorMessage, part.resultText].find(value => typeof value === 'string' && value.trim() !== '');
  const type = typeof part.errorType === 'string' && part.errorType.trim() !== '' ? part.errorType : 'error';
  card.append(el('pre', '', message === undefined ? type : `${type}: ${message}`));
}
